package com.shopsphere.network.client;import java.io.*;import java.net.*;public class InventoryClient{public static void main(String[]x)throws Exception{for(String q:new String[]{"GET_PRODUCT 1","GET_STOCK 2"})try(Socket s=new Socket("localhost",5050)){PrintWriter out=new PrintWriter(s.getOutputStream(),true);ObjectInputStream in=new ObjectInputStream(s.getInputStream());out.println(q);System.out.println(q+" -> "+in.readObject());}}}
